"""Independent saved aggregation/search checks and report for MG166."""
import time,math,hashlib
import numpy as np
from analyze_mg166 import OUT,SYN,PRIOR,OLD,ROOT,Joint,read,atomic_json

def report():
    start=time.perf_counter();s=read(OUT/'analysis.json');checks=0;searchchecks=0;bench=read(PRIOR/'benchmark.json')
    with np.load(OLD/'prepared_inputs.npz') as z:ref=z['reference'];initial=z['initial'];omega=float(z['omega'])
    with np.load(OUT/'compact_projections_and_veto.npz') as z:
        for row in s['averaging']:
            ri=[.1,.5,1.].index(row['regime']);values=z[f'r{ri}_projections'];values=values[:2] if row['group']=='development_r0r1' else values[2:];M=row['M'];cs=np.concatenate([np.zeros((*values.shape[:2],1)),np.cumsum(values,axis=2)],axis=2);ends=np.arange(M,102,M);means=(cs[:,:,ends]-cs[:,:,ends-M])/M;flat=means.ravel();mean=sum(map(float,flat))/len(flat);var=sum((float(v)-mean)**2 for v in flat)/(len(flat)-1);np.testing.assert_allclose(var,row['variance'],rtol=1e-11);checks+=1
        for ri,regime in enumerate(bench['regime_inputs']):
            model=Joint(ref,initial,omega,np.array(regime['covariance']))
            for case in('intact_0','intact_1','intact_2','split'):
                flags=z[f'r{ri}_{case}_veto'];ratios=z[f'r{ri}_{case}_ratios'];row=next(r for r in s['veto'] if r['regime']==regime['time'] and r['case']==case);assert int(flags.sum())==row['vetoes'];assert row['screen_passed']==(flags.mean()>=.9 if case=='split' else flags.mean()<=.05);checks+=1
                with np.load(SYN/f'r{ri}_{case}.npz') as raw:field=raw['fields'][0];field-=field.mean(axis=1)[:,None]
                rolls=np.array([np.roll(field,-k,axis=1).ravel() for k in range(500)]);dot=model.k.reshape(23,-1)@rolls.T;gain=np.maximum(dot,0)**2/model.norm[:,None];si,k=np.unravel_index(gain.argmax(),gain.shape);dist=np.minimum((np.arange(500)-k)%500,(k-np.arange(500))%500)*model.x.h;second=gain[:,dist>model.x.background_exclusion].max();ratio=second/gain[si,k];np.testing.assert_allclose(ratio,ratios[0],rtol=1e-10);assert bool(flags[0])==bool(second>bench['calibrations'][ri]['score'] and ratio>=.5);searchchecks+=1
    # Independent CDF calculation of stated Gaussian separation/power target.
    alpha_threshold=1.6448536269514722;power=.5*math.erfc(-(s['gaussian_target_separation']-alpha_threshold)/math.sqrt(2));assert abs(power-.9)<1e-12
    assert all(r['screen_passed'] for r in s['veto'])==s['veto_development_screen_passed'];atomic_json(OUT/'separate_check.json',dict(passed=True,aggregation_and_verdict_checks=checks,direct_spatial_search_checks=searchchecks,Gaussian_target_power_erfc=power,scope='Independent cumulative-sum block aggregation, direct full spatial search and erfc power check; same author/shared fields/templates.'))
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    fig,axes=plt.subplots(1,2,figsize=(11,4.5),layout='constrained')
    for group,style in [('development_r0r1','-'),('seen_check_r2r3','--')]:
        for t,color in zip((.1,.5,1.),('tab:blue','tab:orange','tab:green')):
            rows=[r for r in s['averaging'] if r['group']==group and r['regime']==t];axes[0].plot([r['M'] for r in rows],[r['standard_deviation_gain'] for r in rows],style+'o',color=color,label=f'T={t:g}, '+('r0/1' if style=='-' else 'r2/3'))
    axes[0].plot([1,2,5,10,20,50],np.sqrt([1,2,5,10,20,50]),':',color='black',label='Independent-sample reference');axes[0].set_xscale('log');axes[0].set_xlabel('Adjacent observations averaged');axes[0].set_ylabel('Projection standard-deviation reduction factor');axes[0].legend(fontsize=7);axes[0].grid(alpha=.2)
    ds=[r for r in s['detectability'] if r['projection']=='G_conditional_GXY'];axes[1].bar([str(r['regime']) for r in ds],[r['SNR'] for r in ds],color='tab:blue');axes[1].axhline(s['gaussian_target_separation'],color='black',ls=':',label='Conditional 5% / 90% target');axes[1].set_xlabel('Noise regime model time');axes[1].set_ylabel('Known-geometry G signal / noise std');axes[1].legend(fontsize=8);axes[1].grid(axis='y',alpha=.2);fig.savefig(OUT/'MG166_detectability_averaging.png',dpi=160);plt.close(fig)
    lines=['# MG166 - G detectability, averaging and competing-core check','',
    'The saved-data study explains why adding G has not made the particle measurement reliable: its reference feature is small relative to the observed background, and nearby time samples do not average that background away efficiently. In a favorable known-position/width calculation, G reaches only about0.4-0.55times the single-frame fluctuation level; covariance weighting adds little. Fifty adjacent observations improve the measured background-projection dispersion by only about1-8%, instead of the sevenfold independent-sample expectation. The competing-core veto works on early synthetic examples but fails the later-noise screen. These findings argue against another long run merely to collect denser snapshots or loosening thresholds; the complete particle remains unresolved, not disproved.','',
    '![Detectability and averaging](MG166_detectability_averaging.png)','',
    '## Scope','',
    'No new Model G trajectories or synthetic fields were generated. Inputs are previously seen MG163 homogeneous coarse observations and MG165v2synthetic benchmark fields. The specification/source/input hashes were published before this calculation. One worker/library-thread1; original criteria and earlier results remain unchanged. A pre-evaluation code review corrected the signal-difference formula to use G-only contrast, not the intact G/X/Y profile; original registration and correction are preserved in Git, with no evaluated attempt discarded.','',
    '## G detectability under the conditional noise model','',
    'The contrast is intact versus Gremoved, with the same known position, width1and known other-species signal. It projects on the reference Gfeature, comparing G-only weighting and full3x3covariance weighting. The latter uses X/Y to condition noise, not to count their unchanged signal as evidence for G. First512nullfields set noise dispersion; last512check it. This fixed-geometry calculation avoids a search penalty, but is not a proof of an optimal spatial estimator or a universal information bound.','',
    '| Noise regime T | G-only signal/noise | Covariance-weighted signal/noise | Ideal independent observations needed |','|---|---:|---:|---:|']
    for t in(.1,.5,1.):
        a=next(r for r in s['detectability'] if r['regime']==t and r['projection']=='G_only');b=next(r for r in s['detectability'] if r['regime']==t and r['projection']=='G_conditional_GXY');lines.append(f"| {t:g} | {a['SNR']:.6g} | {b['SNR']:.6g} | {b['ideal_independent_count']} |")
    lines+=['',
    'The last column is a conditional Gaussian planning calculation: known-geometry one-sided false-positive probability5%and power90%requires signal separation2.92641noise standard deviations. Independent averaging reduces noise by sqrt(M), yielding29-55observations for this covariance-weighted projection. It is not a measured number of independent frames, a registered production sample size, or a claim that the actual state stays unchanged while collecting them. Conditional synthetic noise and estimated variance are assumptions, not independently validated real-field coverage.','',
    '## What adjacent-time averaging actually does','',
    'For each of four homogeneous coarse paths, project the processed G/X/Y field on the Gcontrast at16fixedglobalcenters. Use101-frame windows T=.05-.15,.45-.55,.9-1, and fixed nonoverlapping averages M=1,2,5,10,20,50, dropping only incomplete tails. No Xtracking/recentering or temporal detrending is introduced. Pooled dispersion includes persistent spatial structure and heterogeneous positions, not merely independent random error. Thus these ratios describe the fields actually present; they do not isolate a stationary temporal noise autocorrelation.','',
    '| Regime T | M50 std reduction, r0/r1 | M50 std reduction, previously seen r2/r3 | Independent reference |','|---|---:|---:|---:|']
    for t in(.1,.5,1.):
        a=next(r for r in s['averaging'] if r['regime']==t and r['group']=='development_r0r1' and r['M']==50);b=next(r for r in s['averaging'] if r['regime']==t and r['group']=='seen_check_r2r3' and r['M']==50);lines.append(f"| {t:g} | {a['standard_deviation_gain']:.6g} | {b['standard_deviation_gain']:.6g} | {np.sqrt(50):.6g} |")
    lines+=['',
    'M50 uses fifty observations spaced0.001apart (a0.049span). It reduces temporal resolution and can blur evolving structures; it is not50independent realizations. Time-persistent structure or correlated fluctuations can survive averaging. The check paths r2/r3are excluded from the noise-regime estimation but already inspected in earlier stages: they are not fresh validation. Mean changes between window halves are exported, so drift is retained rather than silently subtracted.','',
    '## Competing-core veto: development screen NOT PASSED','',
    'The frozen veto searches a second gain maximum farther than2R95from the best center. It rejects if that second gain exceeds the existing null threshold and is at least half the first. Thresholds and distances were not retuned. This is a separate candidate check, not a repair that qualifies MG165.','',
    '| Regime T | Intact cores falsely vetoed (all3cases) | Double cores caught | Required double-core fraction |','|---|---:|---:|---:|']
    for t in(.1,.5,1.):
        intact=[r for r in s['veto'] if r['regime']==t and r['case']!='split'];split=next(r for r in s['veto'] if r['regime']==t and r['case']=='split');lines.append(f"| {t:g} | {sum(r['vetoes'] for r in intact)}/384 | {split['vetoes']}/128 ({100*split['fraction']:.6g}%) | >=90% |")
    lines+=['',
    'The weak later cores may not generate a detectable second peak. Zero observed false vetoes in these finite examples is not a population-zero error rate. Tests reuse the old conditional synthetic validation fields and cannot certify generalization to new noise or real trajectories. All intact cases met the <=5%false-veto screen, while the split cases failed atT.5andT1.','',
    '## Checks and retention','',
    f"The primary analysis passed {s['projection_checks']}direct spatial projection checks. Separate cumulative-sum aggregation/verdict checks passed {checks}records; independent full-bank direct spatial searches passed {searchchecks}veto examples. The Gaussian target was checked separately with erfc. Shared input arrays/templates remain dependencies; same-author checks are not external replication. Analysis elapsed {s['elapsed_seconds']:.6g}seconds. Compact projection histories/veto flags, input hashes, full precision summaries and timings are retained; original full fields remain local. No complete particle score or persistence rescore was issued.",'',
    '## Recommended next step','',
    'Prepare a narrowly defined X/Y core detector, retaining G as a separately reported unresolved component rather than forcing weak G into a particle pass/fail average. First quantify X/Y intact-versus-damaged and single-versus-double detectability across the same evolving-noise regimes, including spatial covariance and shape families; use new independent validation fields after freezing choices. If a full G/X/Y claim remains essential, estimate the cost of genuinely independent realizations or a validated dynamical/time-series inference model. Do not substitute adjacent frames for independent replicates. Any fresh kinetic allocation requires its own concrete budget. No new simulations are started or authorized by this report.','']
    text='\n'.join(lines)
    for a,b in [('about0.4','about 0.4'),('about1-8%','about 1-8%'),('MG165v2synthetic','MG165 v2 synthetic'),('Gremoved','G removed'),('width1and','width 1 and'),('Gfeature','G feature'),('full3x3covariance','full 3x3 covariance'),('First512nullfields','First 512 null fields'),('last512check','last 512 check'),('probability5%and power90%requires','probability 5% and power 90% requires'),('separation2.92641noise','separation 2.92641 noise'),('yielding29-55observations','yielding 29-55 observations'),('Gcontrast at16fixedglobalcenters','G contrast at 16 fixed global centers'),('Use101-frame','Use 101-frame'),('spaced0.001apart (a0.049span)','spaced 0.001 apart (a 0.049 span)'),('not50independent','not 50 independent'),('r2/r3are','r2/r3 are'),('than2R95from','than 2R95 from'),('all3cases','all 3 cases'),('<=5%false-veto','<=5% false-veto'),('atT.5andT1','at T=0.5 and T=1'),('}direct','} direct'),('}records','} records'),('}veto','} veto'),('}seconds','} seconds')]:text=text.replace(a,b)
    (OUT/'MG166_detectability_results.md').write_text(text,encoding='utf-8');atomic_json(OUT/'report_attempt.json',dict(status='COMPLETE',elapsed_seconds=time.perf_counter()-start))
